    try:
        example = [2, 6, 1, 3, 4, 5, 7]
        result = longest_consecutive_subsequence(example)
        print(f"Longest consecutive subsequence length: {result}")
    except (TypeError, ValueError) as e:
        print(f"Error: {e}")


